// Hand-written (not generated by orval): the universal scan returns either a
// plant or an insect result, which the generator does not model well.
// Documented in lib/api-spec/openapi.yaml as POST /scan (operationId scanAuto).
import { customFetch } from "./custom-fetch";
import type {
  PlantScanResult,
  ScanInsectInput,
  ScanInsectResult,
} from "./generated/api.schemas";

export type ScanAutoResult = PlantScanResult | ScanInsectResult;

export function isInsectScanResult(r: ScanAutoResult): r is ScanInsectResult {
  return "insect" in r && !!(r as ScanInsectResult).insect;
}

export const scanAuto = (
  input: ScanInsectInput,
  options?: RequestInit,
): Promise<ScanAutoResult> =>
  customFetch<ScanAutoResult>(`/api/scan`, {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(input),
  });
